ref_postcond:
@icontract.ensure(
    lambda result, number:
        1 <= result <= 4
        and
        result == (
            1
            if (math.isqrt(number) ** 2 == number)
            else (
                4
                if (
                    (lambda n:
                        0
                        if n == 0
                        else n >> (
                            2 * (
                                ((n & -n).bit_length() - 1) // 2
                            )
                        )
                    )(number)
                    % 8 == 7
                )
                else (
                    2
                    if any(
                        (lambda x: math.isqrt(x) ** 2 == x)(number - i * i)
                        for i in range(1, math.isqrt(number) + 1)
                    )
                    else 3
                )
            )
        )
)

